-- 세트 542. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set542.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 542, 'sudo 위임 실습: visudo·그룹 위임·특정 명령만·NOPASSWD', '`sudoers` 를 읽는 법(세트 426)을 배운 뒤, 직접 써 봅니다. `visudo -c` 로 문법을 검사하고 `/etc/sudoers.d/` 에 0440 파일로 규칙을 넣고, `%그룹` 에 권한을 위임하고, 전권 대신 특정 명령만 허용하고, `sudo -l -U` 로 결과를 확인하고, 파일 이름 때문에 무시되는 규칙을 고치고, 넓은 `NOPASSWD: ALL` 을 꼭 필요한 명령 하나로 좁힙니다. 샌드박스에서 sudo 를 설치해 실제로 동작시킵니다.', 'linux', '리눅스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 542);
UPDATE quest_set SET display_order = 801, unit_id = (SELECT id FROM unit WHERE id = 59), icon = '🔑' WHERE id = 542;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 1, '왜 sudoers 는 visudo 로 고칠까', '`/etc/sudoers` 를 `vi /etc/sudoers` 로 바로 열어 고치지 말고 `visudo` 를 쓰라는 말을 자주 듣습니다. `visudo` 를 쓰는 가장 알맞은 이유는 무엇일까요?', 'sudoers 에 오타가 있는 채로 저장되면 어떤 일이 벌어질지 생각해 보세요. 그 문제를 막아 주는 장치가 편집기 바깥에 있습니다.', NULL, NULL, '[]', 'choice', '["저장할 때 문법을 검사해서 오타가 있으면 반영을 막고, 동시에 두 사람이 고치지 못하게 잠근다", "root 암호 없이도 sudoers 를 편집할 수 있게 해 준다", "sudoers 내용을 암호화해서 저장한다", "vi 가 지원하지 않는 한글 입력을 지원한다"]', 0, '문법 오류가 있는 sudoers 는 sudo 가 규칙을 읽지 못하게 만들어, 모든 사용자의 sudo 가 막힐 수 있습니다. root 로 로그인할 수 없는 서버라면 복구가 어려워집니다. `visudo` 는 편집 파일을 잠그고(동시 편집 방지), 저장할 때 문법을 검사해 오류가 있으면 다시 편집할지 묻습니다. 파일만 검사하려면 `visudo -c`(현재 설정) 또는 `visudo -cf 파일` 을 씁니다. 편집 내용을 암호화하거나 권한 없이 편집하게 해 주지는 않습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 2, '오타 난 규칙을 검사해서 고치고 설치하기', 'alice 가 root 권한으로 `/usr/bin/id` 만 실행할 수 있게 하려고 규칙 초안을 `/tmp/alice.draft` 에 적어 두었는데 오타가 있는 것 같습니다. 이 초안은 실제 sudoers 에 넣기 전이라 아직 안전합니다.

1. `visudo` 의 **파일 검사** 기능으로 초안이 맞는지 확인하고 오류를 고치세요.
2. 고친 규칙을 **`/etc/sudoers.d/alice`** 로 설치하고, 파일 권한은 sudoers 파일의 표준인 **0440**(소유자·그룹 읽기 전용)으로 하세요.

(sudoers.d 안의 파일 하나가 문법 오류이면 sudo 전체가 막힐 수 있으니, 설치 전에 검사하는 습관이 중요합니다.)', '`visudo -h` 에서 "문법만 검사"하는 옵션과 "대상 파일을 지정"하는 옵션을 찾아보세요. 오류 메시지가 가리키는 줄과 칸을 보면 무엇이 빠졌는지 보입니다. 권한은 `chmod` 로 숫자 모드를 줍니다.', 'visudo -cf /tmp/alice.draft          # syntax error 가 나온다. 규칙에 ''='' 가 빠졌다
sed -i ''s/ALL (root)/ALL=(root)/'' /tmp/alice.draft
visudo -cf /tmp/alice.draft          # parsed OK
cp /tmp/alice.draft /etc/sudoers.d/alice
chmod 0440 /etc/sudoers.d/alice
sudo -l -U alice                     # (root) /usr/bin/id 가 보인다', '["sh", "-c", "command -v sudo >/dev/null || { apt-get update -qq && apt-get install -y -qq sudo; } >/dev/null 2>&1\\nfind /etc/sudoers.d -type f ! -name README -delete; rm -rf /tmp/*.draft /tmp/*.rule /tmp/app-restarted /usr/local/bin/restart-app.sh; for u in alice carol dave gina hank frank deploy; do userdel -r $u >/dev/null 2>&1; done; for g in ops webdev; do groupdel $g >/dev/null 2>&1; done\\nuseradd -m alice; echo ''alice ALL (root) /usr/bin/id'' > /tmp/alice.draft\\n"]', '["sh", "-c", "( visudo -cf /etc/sudoers.d/alice >/dev/null 2>&1 ) && ( [ \\"$(stat -c %a /etc/sudoers.d/alice)\\" = 440 ] ) && ( sudo -l -U alice 2>/dev/null | grep -q \\"(root) /usr/bin/id\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "설치한 파일이 문법 검사를 통과한다", "cmd": ["sh", "-c", "visudo -cf /etc/sudoers.d/alice >/dev/null 2>&1"]}, {"label": "파일 권한이 0440 이다", "cmd": ["sh", "-c", "[ \\"$(stat -c %a /etc/sudoers.d/alice)\\" = 440 ]"]}, {"label": "alice 가 /usr/bin/id 를 root 로 실행할 수 있다", "cmd": ["sh", "-c", "sudo -l -U alice 2>/dev/null | grep -q \\"(root) /usr/bin/id\\""]}]', '[{"title": "sudoers 매뉴얼", "url": "https://www.sudo.ws/docs/man/sudoers.man/"}, {"title": "visudo 매뉴얼", "url": "https://www.sudo.ws/docs/man/visudo.man/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 3, '그룹 전체에 위임하기: %ops', '운영팀 계정마다 규칙을 따로 쓰면 사람이 바뀔 때마다 sudoers 를 고쳐야 합니다. 대신 **그룹**에 권한을 주면 그룹 가입만으로 위임됩니다. 규칙에서 그룹 이름 앞에는 `%` 를 붙입니다.

이미 만들어 둔 `ops` 그룹(멤버: carol)이 **root 권한으로 모든 명령**을 실행할 수 있게 **`/etc/sudoers.d/ops`** 에 규칙을 넣으세요(파일 권한 0440, 문법 검사 통과). `ops` 에 속하지 않은 dave 는 여전히 sudo 를 쓸 수 없어야 합니다. (운영팀 전권은 입문용 예시이고, 다음 문제에서 범위를 좁힙니다.)', '규칙 형식은 `누가 호스트=(실행계정) 명령` 입니다. 개인 사용자 자리에 그룹 표기를 쓰면 됩니다. 쓴 뒤 `visudo -cf` 로 검사하고 `sudo -l -U carol` 로 확인하세요.', 'echo ''%ops ALL=(ALL) ALL'' > /etc/sudoers.d/ops
chmod 0440 /etc/sudoers.d/ops
visudo -cf /etc/sudoers.d/ops
sudo -l -U carol    # (ALL) ALL
sudo -l -U dave     # not allowed to run sudo', '["sh", "-c", "command -v sudo >/dev/null || { apt-get update -qq && apt-get install -y -qq sudo; } >/dev/null 2>&1\\nfind /etc/sudoers.d -type f ! -name README -delete; rm -rf /tmp/*.draft /tmp/*.rule /tmp/app-restarted /usr/local/bin/restart-app.sh; for u in alice carol dave gina hank frank deploy; do userdel -r $u >/dev/null 2>&1; done; for g in ops webdev; do groupdel $g >/dev/null 2>&1; done\\ngroupadd ops; useradd -m -G ops carol; useradd -m dave\\n"]', '["sh", "-c", "( grep -rqE \\"^%ops[[:space:]]\\" /etc/sudoers.d ) && ( sudo -l -U carol 2>/dev/null | grep -Eq \\"\\\\) +ALL$\\" ) && ( sudo -l -U dave 2>&1 | grep -q \\"not allowed\\" ) && ( [ \\"$(stat -c %a /etc/sudoers.d/ops)\\" = 440 ] && visudo -c >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "/etc/sudoers.d 에 %ops 규칙이 있다", "cmd": ["sh", "-c", "grep -rqE \\"^%ops[[:space:]]\\" /etc/sudoers.d"]}, {"label": "carol(ops 멤버)이 모든 명령을 실행할 수 있다", "cmd": ["sh", "-c", "sudo -l -U carol 2>/dev/null | grep -Eq \\"\\\\) +ALL$\\""]}, {"label": "dave 는 sudo 를 쓸 수 없다", "cmd": ["sh", "-c", "sudo -l -U dave 2>&1 | grep -q \\"not allowed\\""]}, {"label": "파일 권한이 0440 이고 문법이 맞다", "cmd": ["sh", "-c", "[ \\"$(stat -c %a /etc/sudoers.d/ops)\\" = 440 ] && visudo -c >/dev/null 2>&1"]}]', '[{"title": "sudoers 매뉴얼", "url": "https://www.sudo.ws/docs/man/sudoers.man/"}, {"title": "visudo 매뉴얼", "url": "https://www.sudo.ws/docs/man/visudo.man/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 4, '특정 명령만 허용하기', '웹 개발팀(`webdev` 그룹, 멤버: gina)은 nginx 를 재시작·리로드만 하면 되는데 전권을 줄 이유가 없습니다. 필요한 명령만 허용하는 것이 **최소 권한 원칙**입니다.

`webdev` 그룹이 root 권한으로 **`/usr/bin/systemctl restart nginx`** 와 **`/usr/bin/systemctl reload nginx`** 두 명령만 실행하도록 **`/etc/sudoers.d/webdev`** 에 규칙을 넣으세요(권한 0440). 명령은 **전체 경로**로 쓰고, `ALL` 이나 `*` 로 범위를 넓히지 마세요. 그룹에 속하지 않은 hank 는 sudo 를 쓸 수 없어야 합니다.', '명령 자리에 허용할 명령을 쉼표로 나열합니다. 인자까지 함께 적은 명령은 그 인자 그대로만 허용됩니다. 확인은 `sudo -l -U gina` 로 합니다.', 'echo ''%webdev ALL=(root) /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx'' > /etc/sudoers.d/webdev
chmod 0440 /etc/sudoers.d/webdev
visudo -cf /etc/sudoers.d/webdev
sudo -l -U gina    # (root) /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx', '["sh", "-c", "command -v sudo >/dev/null || { apt-get update -qq && apt-get install -y -qq sudo; } >/dev/null 2>&1\\nfind /etc/sudoers.d -type f ! -name README -delete; rm -rf /tmp/*.draft /tmp/*.rule /tmp/app-restarted /usr/local/bin/restart-app.sh; for u in alice carol dave gina hank frank deploy; do userdel -r $u >/dev/null 2>&1; done; for g in ops webdev; do groupdel $g >/dev/null 2>&1; done\\ngroupadd webdev; useradd -m -G webdev gina; useradd -m hank\\n"]', '["sh", "-c", "( sudo -l -U gina 2>/dev/null | grep -q \\"/usr/bin/systemctl restart nginx\\" ) && ( sudo -l -U gina 2>/dev/null | grep -q \\"/usr/bin/systemctl reload nginx\\" ) && ( ! sudo -l -U gina 2>/dev/null | grep -Eq \\"\\\\) +(NOPASSWD: +)?ALL$|[*]\\" ) && ( sudo -l -U hank 2>&1 | grep -q \\"not allowed\\" ) && ( [ \\"$(stat -c %a /etc/sudoers.d/webdev)\\" = 440 ] && visudo -c >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "gina 가 restart nginx 를 실행할 수 있다", "cmd": ["sh", "-c", "sudo -l -U gina 2>/dev/null | grep -q \\"/usr/bin/systemctl restart nginx\\""]}, {"label": "gina 가 reload nginx 를 실행할 수 있다", "cmd": ["sh", "-c", "sudo -l -U gina 2>/dev/null | grep -q \\"/usr/bin/systemctl reload nginx\\""]}, {"label": "전권(ALL)이나 와일드카드(*)로 넓히지 않았다", "cmd": ["sh", "-c", "! sudo -l -U gina 2>/dev/null | grep -Eq \\"\\\\) +(NOPASSWD: +)?ALL$|[*]\\""]}, {"label": "hank 는 sudo 를 쓸 수 없다", "cmd": ["sh", "-c", "sudo -l -U hank 2>&1 | grep -q \\"not allowed\\""]}, {"label": "파일 권한이 0440 이고 문법이 맞다", "cmd": ["sh", "-c", "[ \\"$(stat -c %a /etc/sudoers.d/webdev)\\" = 440 ] && visudo -c >/dev/null 2>&1"]}]', '[{"title": "sudoers 매뉴얼", "url": "https://www.sudo.ws/docs/man/sudoers.man/"}, {"title": "visudo 매뉴얼", "url": "https://www.sudo.ws/docs/man/visudo.man/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 5, '허용한 명령이 전권이 되는 경우', '`webdev` 에게 nginx 설정을 고치게 하려고 `%webdev ALL=(root) /usr/bin/vim /etc/nginx/nginx.conf` 를 넣었습니다. 파일 경로까지 고정했으니 안전하다고 생각했는데, 보안 담당자는 "사실상 root 전권을 준 것"이라고 합니다. 가장 알맞은 이유는 무엇일까요?', '`vim` 이 root 로 떠 있는 동안 그 프로그램 **안에서** 할 수 있는 일이 무엇인지, 인자 제한이 그것까지 막아 주는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["root 로 뜬 vim 안에서 셸을 실행하거나 다른 파일을 열 수 있어, 그 시점부터 root 셸을 얻은 것과 같다", "`/etc/nginx/nginx.conf` 외의 인자가 붙으면 sudo 가 명령 자체를 무시하기 때문이다", "vim 은 전체 경로로 실행하면 root 권한이 적용되지 않기 때문이다", "규칙에 그룹을 쓰면 인자 제한이 전부 무시되기 때문이다"]', 0, 'root 로 실행된 vim 안에서 `:!sh` 나 `:e 다른파일` 같은 기능을 쓰면 인자 제한은 아무 소용이 없습니다. 이처럼 **셸 탈출이 가능한 프로그램**(편집기·pager·`less`·`find -exec` 등)이나 임의의 파일을 쓰는 명령을 위임하면 사실상 전권입니다. 파일 편집만 위임하려면 `%webdev ALL=(root) sudoedit /etc/nginx/nginx.conf` 처럼 `sudoedit` 를 쓰세요. sudoedit 는 편집기를 **일반 사용자 권한**으로 띄우고 임시 파일을 복사해 저장하는 방식이라 셸 탈출이 root 로 이어지지 않습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 6, '다른 사용자의 sudo 권한 목록 보기', '관리자(root)가 carol 에게 어떤 sudo 권한이 있는지 **carol 로 로그인하지 않고** 확인하려고 합니다. 빈칸에 알맞은 옵션을 넣으세요. (`-U 계정` 은 "그 계정 기준으로"라는 뜻입니다.)', '`sudo -h` 에서 "허용된 명령을 보여 주는" 옵션을 찾아보세요. 암호 캐시를 다루는 옵션은 목록을 보여 주지 않습니다.', NULL, NULL, '[]', 'fill', '["-l", "-k", "-v", "-s"]', NULL, '`sudo -l`(list)은 **나에게 허용된 명령**을, root 가 `sudo -l -U 계정` 으로 쓰면 **그 계정의 권한**을 보여 줍니다. "no rules"가 아니라 `User carol is not allowed to run sudo` 가 나오면 아무 규칙도 적용되지 않은 것입니다. `-v` 는 암호 캐시 갱신, `-k` 는 캐시 만료, `-s` 는 셸 실행이라 목록을 보여 주지 않습니다. 새 규칙을 넣은 뒤에는 `sudo -l -U` 로 **의도한 것만 허용되는지** 확인하는 습관을 들이세요.', '[0]', 'sudo {0} -U carol', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 7, '규칙이 적용되지 않는 이유: 파일 이름', 'frank 가 `/usr/bin/id` 를 root 로 실행할 수 있게 `/etc/sudoers.d/frank.rules` 에 규칙을 넣었는데 `sudo -l -U frank` 는 "not allowed to run sudo" 라고 합니다. 파일의 문법은 틀리지 않았습니다.

`sudoers.d` 디렉터리는 **이름 규칙**에 맞는 파일만 읽습니다. 원인을 찾아 `sudo -l -U frank` 에 `/usr/bin/id` 가 보이도록 고치세요. (규칙 내용은 그대로 두고 이름만 바꾸면 됩니다.)', '먼저 `sudo -l -U frank` 와 `visudo -c` 의 출력을 보고, `/etc/sudoers.d/README` 를 읽어 보세요. 읽지 않고 건너뛰는 파일이 어떤 이름인지 적혀 있습니다.', 'visudo -c                           # frank.rules 는 목록에 없다(건너뜀)
cat /etc/sudoers.d/README | head   # ''.'' 가 들어간 이름과 ~ 로 끝나는 이름은 건너뜀
mv /etc/sudoers.d/frank.rules /etc/sudoers.d/frank
sudo -l -U frank                    # (root) /usr/bin/id', '["sh", "-c", "command -v sudo >/dev/null || { apt-get update -qq && apt-get install -y -qq sudo; } >/dev/null 2>&1\\nfind /etc/sudoers.d -type f ! -name README -delete; rm -rf /tmp/*.draft /tmp/*.rule /tmp/app-restarted /usr/local/bin/restart-app.sh; for u in alice carol dave gina hank frank deploy; do userdel -r $u >/dev/null 2>&1; done; for g in ops webdev; do groupdel $g >/dev/null 2>&1; done\\nuseradd -m frank; echo ''frank ALL=(root) /usr/bin/id'' > /etc/sudoers.d/frank.rules; chmod 0440 /etc/sudoers.d/frank.rules\\n"]', '["sh", "-c", "( sudo -l -U frank 2>/dev/null | grep -q \\"(root) /usr/bin/id\\" ) && ( visudo -c >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "frank 가 /usr/bin/id 를 root 로 실행할 수 있다", "cmd": ["sh", "-c", "sudo -l -U frank 2>/dev/null | grep -q \\"(root) /usr/bin/id\\""]}, {"label": "sudoers 전체 문법이 맞다", "cmd": ["sh", "-c", "visudo -c >/dev/null 2>&1"]}]', '[{"title": "sudoers 매뉴얼", "url": "https://www.sudo.ws/docs/man/sudoers.man/"}, {"title": "visudo 매뉴얼", "url": "https://www.sudo.ws/docs/man/visudo.man/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 8, 'NOPASSWD: ALL 을 필요한 명령 하나로 좁히기', '배포 자동화 계정 `deploy` 가 암호 없이 `sudo` 를 쓰도록 누군가 `/etc/sudoers.d/deploy` 에 `deploy ALL=(ALL) NOPASSWD: ALL` 을 넣어 두었습니다. 그런데 배포 스크립트가 root 로 하는 일은 `/usr/local/bin/restart-app.sh` 실행 하나뿐입니다. (`NOPASSWD:` 는 해당 명령에서 암호를 묻지 않는 태그입니다.)

`/etc/sudoers.d/deploy` 를 고쳐 `deploy` 가 **암호 없이는 그 스크립트만** 실행하도록 좁히세요. 완료 뒤에는
- deploy 가 `sudo -n /usr/local/bin/restart-app.sh` 를 암호 없이 실행할 수 있고(`-n` 은 암호를 묻지 말고 안 되면 실패하라는 옵션),
- 그 밖의 명령(예: `sudo -n /usr/bin/id`)은 암호 없이 실행할 수 없어야 하며,
- 문법 검사도 통과해야 합니다.', '`NOPASSWD:` 뒤의 명령 자리가 `ALL` 이어서 문제입니다. 허용할 명령의 전체 경로로 바꾸세요. 고친 뒤 `su deploy -s /bin/bash -c "sudo -n 명령"` 으로 deploy 의 입장에서 시험해 볼 수 있습니다.', 'cat /etc/sudoers.d/deploy
echo ''deploy ALL=(root) NOPASSWD: /usr/local/bin/restart-app.sh'' > /etc/sudoers.d/deploy
visudo -cf /etc/sudoers.d/deploy
su deploy -s /bin/bash -c ''sudo -n /usr/local/bin/restart-app.sh''   # 성공
su deploy -s /bin/bash -c ''sudo -n /usr/bin/id''                      # a password is required', '["sh", "-c", "command -v sudo >/dev/null || { apt-get update -qq && apt-get install -y -qq sudo; } >/dev/null 2>&1\\nfind /etc/sudoers.d -type f ! -name README -delete; rm -rf /tmp/*.draft /tmp/*.rule /tmp/app-restarted /usr/local/bin/restart-app.sh; for u in alice carol dave gina hank frank deploy; do userdel -r $u >/dev/null 2>&1; done; for g in ops webdev; do groupdel $g >/dev/null 2>&1; done\\nuseradd -m deploy; printf ''#!/bin/sh\\\\ntouch /tmp/app-restarted\\\\n'' > /usr/local/bin/restart-app.sh; chown root:root /usr/local/bin/restart-app.sh; chmod 755 /usr/local/bin/restart-app.sh; echo ''deploy ALL=(ALL) NOPASSWD: ALL'' > /etc/sudoers.d/deploy; chmod 0440 /etc/sudoers.d/deploy\\n"]', '["sh", "-c", "( rm -f /tmp/app-restarted; su deploy -s /bin/bash -c \\"sudo -n /usr/local/bin/restart-app.sh\\" >/dev/null 2>&1 && [ -e /tmp/app-restarted ] ) && ( ! su deploy -s /bin/bash -c \\"sudo -n /usr/bin/id\\" >/dev/null 2>&1 ) && ( visudo -c >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "deploy 가 스크립트를 암호 없이 실행할 수 있다", "cmd": ["sh", "-c", "rm -f /tmp/app-restarted; su deploy -s /bin/bash -c \\"sudo -n /usr/local/bin/restart-app.sh\\" >/dev/null 2>&1 && [ -e /tmp/app-restarted ]"]}, {"label": "그 밖의 명령은 암호 없이 실행되지 않는다", "cmd": ["sh", "-c", "! su deploy -s /bin/bash -c \\"sudo -n /usr/bin/id\\" >/dev/null 2>&1"]}, {"label": "sudoers 전체 문법이 맞다", "cmd": ["sh", "-c", "visudo -c >/dev/null 2>&1"]}]', '[{"title": "sudoers 매뉴얼", "url": "https://www.sudo.ws/docs/man/sudoers.man/"}, {"title": "visudo 매뉴얼", "url": "https://www.sudo.ws/docs/man/visudo.man/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 9, 'NOPASSWD: ALL 의 위험', '배포 계정 `deploy` 에 `NOPASSWD: ALL` 을 주면 편하지만 위험하다고 합니다. 가장 알맞은 위험 설명은 무엇일까요?', '암호를 묻는 절차가 "다른 사람이 내 계정을 쓰고 있다"는 사실을 어떻게 막아 주는지 떠올려 보세요. 그 장벽이 없어지면 어떻게 될까요?', NULL, NULL, '[]', 'choice', '["deploy 계정이나 그 계정으로 도는 스크립트·SSH 키가 탈취되면, 추가 암호 없이 바로 모든 명령을 root 로 실행할 수 있다", "NOPASSWD 를 쓰면 sudo 가 실행 기록을 남기지 않아 추적할 수 없다", "NOPASSWD 는 root 암호를 바꾸므로 다른 관리자가 로그인할 수 없게 된다", "NOPASSWD 규칙은 sudoers.d 에서는 동작하지 않는다"]', 0, '암호 입력은 계정이 뚫렸을 때의 **마지막 방어선**입니다. `NOPASSWD: ALL` 이면 그 계정을 얻은 공격자(또는 계정 권한으로 도는 취약한 스크립트)가 곧바로 root 가 됩니다. 불가피하게 암호 없이 써야 한다면 **필요한 명령만 NOPASSWD** 로 허용하고, 명령 파일은 root 소유로 일반 사용자가 못 고치게 해야 합니다(고칠 수 있으면 그 파일 자체가 root 로 가는 길이 됩니다). sudo 는 NOPASSWD 여도 실행 기록을 남기며 root 암호도 바꾸지 않습니다. NOPASSWD 는 sudoers.d 에서도 잘 동작합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 542, 10, '안전하게 규칙 추가하기: 작성부터 실제 실행까지', '새 위임 규칙을 **서비스 중인 서버에 안전하게** 넣는 순서입니다. 초안은 `/tmp` 에 쓰고, 문법 검사를 통과한 **다음에** `/etc/sudoers.d/` 에 설치하며, 설치한 규칙은 **목록으로 확인한 뒤** 마지막에 해당 계정으로 실제 실행해 봅니다. 카드를 순서대로 놓으세요.', '오류가 있는 파일이 실제 설정 위치에 들어가는 순간이 가장 위험합니다. 그 순간 앞에 어떤 단계가 있어야 할지, 뒤에는 어떤 확인이 이어질지 생각해 보세요.', NULL, NULL, '[]', 'order', '["`visudo -cf /tmp/new.rule` 로 초안의 문법을 검사한다", "`/etc/sudoers.d/` 에 복사하고 권한을 0440 으로 맞춘다", "해당 계정으로 `sudo -n 명령` 을 실제로 실행해 본다", "`/tmp/new.rule` 에 초안을 작성한다", "`sudo -l -U 계정` 으로 의도한 명령만 허용되는지 확인한다"]', NULL, '초안 작성 → 문법 검사 → 설치(0440) → `sudo -l -U` 로 허용 목록 확인 → 실제 실행 순서입니다. 검사를 설치 전에 해야 오류 있는 파일이 sudoers.d 에 들어가 모든 사용자의 sudo 를 막는 사고를 피합니다. `visudo -f /etc/sudoers.d/이름` 으로 바로 편집하면 저장 시 자동으로 검사됩니다. 마지막의 `sudo -n` 은 암호를 묻지 말고 안 되면 실패하라는 옵션이라, NOPASSWD 로 허용한 명령이 정말 동작하는지 자동화 환경 그대로 시험하기 좋습니다.', '[3, 0, 1, 4, 2]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 542 AND order_index = 10);
